import re, sys

# Extract all \cite{...} keys from tex files
tex_files = ['introduction.tex', 'method.tex', 'experiments.tex', 'conclusion.tex', 'related_work.tex', 'appendix.tex']
cited = set()
for f in tex_files:
    content = open(f).read()
    for m in re.finditer(r'\\\\cite\{([^}]+)\}', content):
        for k in m.group(1).split(','):
            cited.add(k.strip())

# Extract all bib keys
bib = open('references.bib').read()
bib_keys = set(re.findall(r'^@\w+\{(\w+)', bib, re.MULTILINE))

# Diff
not_in_bib = cited - bib_keys
not_cited = bib_keys - cited

if not_in_bib:
    print(f'CITED BUT NOT IN BIB ({len(not_in_bib)}):')
    for k in sorted(not_in_bib):
        print(f'  {k}')
else:
    print('All citations found in bib: OK')

if not_cited:
    print(f'IN BIB BUT NEVER CITED ({len(not_cited)}):')
    for k in sorted(not_cited):
        print(f'  {k}')
else:
    print('No orphan bib entries: OK')

print(f'Total cited: {len(cited)}, Total bib: {len(bib_keys)}')
"

